  1	import { test } from 'node:test';
  2	import assert from 'node:assert/strict';
  3	import * as fs from 'node:fs';
  4	import * as os from 'os';
  5	import * as path from 'node:path';
  6	import { Router } from '../../router.js';
  7	import { registerConfigRoutes } from '../../routes/config.js';
  8	import type { AppConfig, GitCredentialEntry } from '../../../config/config.types.js';
  9	import type { PollingManager } from '../../pollingManager.js';
 10	import type { ErrorLogManager } from '../../../error-log/error-log.manager.js';
 11	import type { ErrorLogEntry } from '../../../error-log/error-log.types.js';
 12	import { mockRequest, mockResponse } from '../helpers/mock-http.js';
 13	
 14	// ---------------------------------------------------------------------------
 15	// Temp dir (cleaned up on process exit)
 16	// ---------------------------------------------------------------------------
 17	
 18	const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'paralizer-config-routes-test-'));
 19	
 20	process.on('exit', () => {
 21	    fs.rmSync(tmpRoot, { recursive: true, force: true });
 22	});
 23	
 24	// ---------------------------------------------------------------------------
 25	// Test fixture helpers
 26	// ---------------------------------------------------------------------------
 27	
 28	/**
 29	 * Creates a minimal valid config.json in a temp subdirectory.
 30	 * Returns the absolute path to the config file.
 31	 */
 32	function makeConfigFile(initial: Record<string, unknown> = {}): string {
 33	    const dir = fs.mkdtempSync(path.join(tmpRoot, 'cfg-'));
 34	    const configPath = path.join(dir, 'config.json');
 35	    const base = {
 36	        projectsFolder: dir,
 37	        storageFolder: dir,
 38	        cloneDepth: 50,
 39	        serverPort: 4200,
 40	        gitPollingIntervalSeconds: 30,
 41	        ...initial,
 42	    };
 43	    fs.writeFileSync(configPath, JSON.stringify(base));
 44	    return configPath;
 45	}
 46	
 47	function makeAppConfig(overrides: Partial<AppConfig> = {}): AppConfig {
 48	    return {
 49	        projectsFolder: tmpRoot,
 50	        storageFolder: tmpRoot,
 51	        cloneDepth: 50,
 52	        serverPort: 4200,
 53	        gitPollingIntervalSeconds: 30,
 54	        notesCardHeight: 220,
 55	        notesColumns: 2,
 56	        ...overrides,
 57	    };
 58	}
 59	
 60	function readConfigFile(configPath: string): Record<string, unknown> {
 61	    return JSON.parse(fs.readFileSync(configPath, 'utf8'));
 62	}
 63	
 64	/**
 65	 * Creates a minimal PollingManager stub that records restart() calls.
 66	 */
 67	function makeMockPollingManager(): PollingManager & { restartCalls: number[]; } {
 68	    const stub = {
 69	        restartCalls: [] as number[],
 70	        restart(intervalSeconds: number): void {
 71	            stub.restartCalls.push(intervalSeconds);
 72	        },
 73	    };
 74	    return stub as unknown as PollingManager & { restartCalls: number[]; };
 75	}
 76	
 77	/**
 78	 * Creates a minimal ErrorLogManager stub that records appended entries.
 79	 */
 80	function makeMockErrorLogManager(): ErrorLogManager & { appendedEntries: Omit<ErrorLogEntry, 'Id' | 'Timestamp'>[]; } {
 81	    const stub = {
 82	        appendedEntries: [] as Omit<ErrorLogEntry, 'Id' | 'Timestamp'>[],
 83	        append(entry: Omit<ErrorLogEntry, 'Id' | 'Timestamp'>): ErrorLogEntry {
 84	            stub.appendedEntries.push(entry);
 85	            return { ...entry, Id: stub.appendedEntries.length, Timestamp: new Date().toISOString() };
 86	        },
 87	    };
 88	    return stub as unknown as ErrorLogManager & { appendedEntries: Omit<ErrorLogEntry, 'Id' | 'Timestamp'>[]; };
 89	}
 90	
 91	function buildSut(
 92	    appConfig: AppConfig,
 93	    configPath: string,
 94	    pollingManager?: PollingManager,
 95	    errorLogManager?: ErrorLogManager,
 96	): Router {
 97	    const router = new Router();
 98	    registerConfigRoutes({ router, appConfig, configPath, pollingManager, errorLogManager });
 99	    return router;
100	}

  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import type { Router } from '../router.js';
  3	import type { AppConfig, GitCredentialEntry } from '../../config/config.types.js';
  4	import type { PollingManager } from '../pollingManager.js';
  5	import type { ErrorLogManager } from '../../error-log/error-log.manager.js';
  6	import { saveConfigField } from '../../config/config.js';
  7	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
  8	import { toKebabCase } from '../../utils/slug.js';
  9	
 10	// Polling-interval bounds — shared with settings UI (gui/public/js/views/settings.js).
 11	import {
 12	    MIN_POLLING_INTERVAL_SECONDS,
 13	    MAX_POLLING_INTERVAL_SECONDS,
 14	    MIN_NOTES_CARD_HEIGHT,
 15	    MAX_NOTES_CARD_HEIGHT,
 16	    MIN_NOTES_COLUMNS,
 17	    MAX_NOTES_COLUMNS,
 18	} from '../../config/config.constants.js';
 19	
 20	// ---------------------------------------------------------------------------
 21	// Helpers
 22	// ---------------------------------------------------------------------------
 23	
 24	/**
 25	 * Masks a credential token for display in API responses.
 26	 * Shows the last 4 characters of the token prefixed with `****`.
 27	 * Tokens shorter than 4 characters are fully masked as `****`.
 28	 */
 29	function maskToken(token: string): string {
 30	    return token.length < 4 ? '****' : '****' + token.slice(-4);
 31	}
 32	
 33	/**
 34	 * Extracts and lowercases the scheme from a URL string (the part before the
 35	 * first `:`). Returns an empty string when no colon is present.
 36	 *
 37	 * @example extractScheme('https://example.com') // → 'https'
 38	 * @example extractScheme('javascript:alert(1)') // → 'javascript'
 39	 */
 40	function extractScheme(url: string): string {
 41	    const colonIdx = url.indexOf(':');
 42	    return colonIdx !== -1 ? url.slice(0, colonIdx).toLowerCase() : '';
 43	}
 44	
 45	/**
 46	 * Type guard that returns `true` when `value` is a finite integer number.
 47	 * Used by PUT route handlers to validate numeric config fields.
 48	 *
 49	 * @param value - The value to test (any type accepted).
 50	 * @returns `true` when `value` is of type `number`, finite, and an integer; `false` otherwise.
 51	 */
 52	function isValidFiniteInteger(value: unknown): value is number {
 53	    return typeof value === 'number' && Number.isFinite(value) && Number.isInteger(value);
 54	}
 55	
 56	/**
 57	 * Returns a copy of the credentials array with all tokens masked.
 58	 */
 59	function buildMaskedCredentials(
 60	    credentials: GitCredentialEntry[] | undefined,
 61	): GitCredentialEntry[] {
 62	    if (!credentials) return [];
 63	    return credentials.map((entry) => ({ ...entry, token: maskToken(entry.token) }));
 64	}
 65	
 66	/**
 67	 * Generates a unique kebab-case ID from a label, appending a numeric suffix
 68	 * (-2, -3, ...) when the base ID is already taken.
 69	 *
 70	 * @param label - The human-readable label to derive an ID from.
 71	 * @param existingIds - The set of IDs already in use; the returned ID is
 72	 *   guaranteed not to be a member of this set.
 73	 * @returns A kebab-case string ID that is unique within `existingIds`.
 74	 *
 75	 * @remarks
 76	 * When `toKebabCase(label)` returns an empty string (e.g. because `label`
 77	 * consists entirely of special characters such as `"!!!"`), the function falls
 78	 * back to `"credential"` as the base ID. Suffix disambiguation (-2, -3, …)
 79	 * is still applied when needed, so labels like `"!!!"` and `"???"` resolve to
 80	 * `"credential"` and `"credential-2"` respectively.
 81	 *
 82	 * @example
 83	 * generateUniqueId('GitHub Personal', new Set())       // → 'github-personal'
 84	 * generateUniqueId('GitHub Personal', new Set(['github-personal'])) // → 'github-personal-2'
 85	 * generateUniqueId('!!!', new Set())                   // → 'credential'
 86	 */
 87	function generateUniqueId(label: string, existingIds: Set<string>): string {
 88	    const baseId = toKebabCase(label) || 'credential';
 89	    let candidateId = baseId;
 90	    let suffix = 2;
 91	    while (existingIds.has(candidateId)) {
 92	        candidateId = `${baseId}-${suffix}`;
 93	        suffix++;
 94	    }
 95	    return candidateId;
 96	}
 97	
 98	// ---------------------------------------------------------------------------
 99	// Route registration
100	// ---------------------------------------------------------------------------

101	
102	// ---------------------------------------------------------------------------
103	// Named-options interface
104	// ---------------------------------------------------------------------------
105	
106	export interface ConfigRoutesOptions {
107	    router: Router;
108	    appConfig: AppConfig;
109	    /** Optional absolute path to `config.json`. Defaults to the tool-root `config.json`. */
110	    configPath?: string;
111	    /** Optional `PollingManager`. When provided, PUT /api/config/polling restarts the loop. */
112	    pollingManager?: PollingManager;
113	    /** Optional `ErrorLogManager`. When provided, credential mutations are audit-logged. */
114	    errorLogManager?: ErrorLogManager;
115	}
116	
117	/**
118	 * Registers REST endpoints for managing application configuration in
119	 * `config.json`.
120	 *
121	 * **Credentials endpoints:**
122	 *
123	 * | Method | Path                              | Description               |
124	 * |--------|-----------------------------------|---------------------------|
125	 * | GET    | /api/config/credentials           | List credentials (masked) |
126	 * | PUT    | /api/config/credentials           | Add / update an entry     |
127	 * | DELETE | /api/config/credentials/:id       | Remove an entry           |
128	 *
129	 * `GET` returns a `GitCredentialEntry[]` array with tokens masked (`****` + last 4 chars).
130	 *
131	 * `PUT` request body: `{ id?: string, label: string, host: string, token: string }`.
132	 * When `id` is omitted, an ID is auto-generated from `label` as a kebab-case string
133	 * with a numeric suffix (-2, -3, …) appended on collision.
134	 * When `id` matches an existing entry, that entry is updated in-place (upsert).
135	 * Response: the updated `GitCredentialEntry[]` array with tokens masked.
136	 *
137	 * `DELETE` response: the remaining `GitCredentialEntry[]` array with tokens masked
138	 * (empty array `[]` when the last entry is removed). Returns 404 when the `id` is unknown.
139	 *
140	 * **Polling endpoints:**
141	 *
142	 * | Method | Path                    | Description                                          |
143	 * |--------|-------------------------|------------------------------------------------------|
144	 * | GET    | /api/config/polling     | Return current `gitPollingIntervalSeconds`           |
145	 * | PUT    | /api/config/polling     | Update the polling interval (min 10 s, max 86400 s)  |
146	 *
147	 * **Webserver URL endpoints:**
148	 *
149	 * | Method | Path                         | Description                              |
150	 * |--------|------------------------------|------------------------------------------|
151	 * | GET    | /api/config/webserver-url    | Return current `webserverUrl` (or null)  |
152	 * | PUT    | /api/config/webserver-url    | Update the webserver URL                 |
153	 *
154	 * **Notes display endpoints:**
155	 *
156	 * | Method | Path                          | Description                                                                                                         |
157	 * |--------|-------------------------------|---------------------------------------------------------------------------------------------------------------------|
158	 * | GET    | /api/config/notes-display     | Return current `notesCardHeight` and `notesColumns`                                                                 |
159	 * | PUT    | /api/config/notes-display     | Update notes display settings (partial updates — all fields optional). Fields: `notesCardHeight` ∈ [120, 800] (integer px), `notesColumns` ∈ [1, 6] (integer) |
160	 *
161	 * Changes take effect immediately (the in-memory `appConfig` is mutated) and
162	 * are persisted to `config.json` via `saveConfigField()`.
163	 *
164	 * **Security:** tokens are never returned in full — only the last 4 characters
165	 * are exposed. The `host` field accepts any non-empty string (no format
166	 * restriction is enforced at this layer).
167	 *
168	 * @param options - Named-options bag: `router`, `appConfig`, optional
169	 *   `configPath` (defaults to tool-root `config.json`), optional
170	 *   `pollingManager` (restarts polling loop when present).
171	 */
172	export function registerConfigRoutes(options: ConfigRoutesOptions): void {
173	    const { router, appConfig, configPath, pollingManager, errorLogManager } = options;
174	    // ------------------------------------------------------------------
175	    // GET /api/config/credentials — list all (tokens masked)
176	    // Returns GitCredentialEntry[] with tokens masked.
177	    // ------------------------------------------------------------------
178	    router.get('/api/config/credentials', (
179	        _req: IncomingMessage,
180	        res: ServerResponse,
181	        _params: Record<string, string>,
182	    ): void => {
183	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
184	    });
185	
186	    // ------------------------------------------------------------------
187	    // PUT /api/config/credentials — add or update a single entry
188	    //
189	    // Request body: { id?: string, label: string, host: string, token: string }
190	    //
191	    // - When `id` is omitted: auto-generates a kebab-case ID from `label`,
192	    //   appending a numeric suffix (-2, -3, …) if needed to avoid collisions.
193	    //   Always creates a new entry.
194	    // - When `id` is provided and matches an existing entry: upserts (replaces)
195	    //   the existing entry in-place.
196	    // - When `id` is provided and does NOT match any existing entry: creates a
197	    //   new entry with the given ID (after checking the ID is not already taken).
198	    //
199	    // Returns 400 when the resulting ID would collide with an existing entry
200	    // that is NOT the one being updated (duplicate-ID rejection).
201	    // ------------------------------------------------------------------
202	    router.put('/api/config/credentials', async (
203	        req: IncomingMessage,
204	        res: ServerResponse,
205	        _params: Record<string, string>,
206	    ): Promise<void> => {
207	        let body: unknown;
208	        try {
209	            body = await parseJsonBody(req);
210	        } catch (err) {
211	            sendError(res, 400, err instanceof Error ? err.message : 'Invalid request body.');
212	            return;
213	        }
214	
215	        if (!isPlainObject(body)) {
216	            sendError(res, 400, 'Request body must be a JSON object.');
217	            return;
218	        }
219	
220	        const { id, label, host, token } = body as {
221	            id?: unknown;
222	            label?: unknown;
223	            host?: unknown;
224	            token?: unknown;
225	        };
226	
227	        // Validate required string fields.
228	        if (typeof label !== 'string' || label.trim() === '') {
229	            sendError(res, 400, 'Missing or invalid field "label": must be a non-empty string.');
230	            return;
231	        }
232	        if (typeof host !== 'string' || host.trim() === '') {
233	            sendError(res, 400, 'Missing or invalid field "host": must be a non-empty string.');
234	            return;
235	        }
236	        // Reject host values containing path separators, null bytes, or whitespace —
237	        // a hostname should contain none of these characters.
238	        if (/[/\\\0\s]/.test(host)) {
239	            sendError(res, 400, 'Invalid field "host": must not contain /, \\, null bytes, or whitespace.');
240	            return;
241	        }
242	        if (typeof token !== 'string' || token.trim() === '') {
243	            sendError(res, 400, 'Missing or invalid field "token": must be a non-empty string.');
244	            return;
245	        }
246	
247	        // Validate optional `id` field when provided.
248	        if (id !== undefined && (typeof id !== 'string' || id.trim() === '')) {
249	            sendError(res, 400, 'Field "id", when provided, must be a non-empty string.');
250	            return;
251	        }
252	
253	        // Per-field length limits.
254	        if (typeof id === 'string' && id.trim().length > 100) {
255	            sendError(res, 400, 'Field "id" must not exceed 100 characters.');
256	            return;
257	        }
258	        if (label.trim().length > 200) {
259	            sendError(res, 400, 'Field "label" must not exceed 200 characters.');
260	            return;
261	        }
262	        if (host.trim().length > 253) {
263	            sendError(res, 400, 'Field "host" must not exceed 253 characters.');
264	            return;
265	        }
266	        if (token.trim().length > 500) {
267	            sendError(res, 400, 'Field "token" must not exceed 500 characters.');
268	            return;
269	        }
270	
271	        const cleanLabel = label.trim();
272	        const cleanHost = host.trim();
273	        const cleanToken = token.trim();
274	
275	        const existingCredentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
276	
277	        let savedEntry: GitCredentialEntry;
278	        let auditOperation: string;
279	
280	        if (id !== undefined) {
281	            // --- Upsert path: id is explicitly provided ---
282	            const cleanId = (id as string).trim();
283	            const existingIndex = existingCredentials.findIndex((e) => e.id === cleanId);
284	
285	            if (existingIndex === -1) {
286	                // New entry with an explicit ID — no existing entry matches, so create.
287	                savedEntry = { id: cleanId, label: cleanLabel, host: cleanHost, token: cleanToken };
288	                appConfig.gitCredentials = [...existingCredentials, savedEntry];
289	                auditOperation = 'create-credential';
290	            } else {
291	                // Replace the existing entry at the same position.
292	                savedEntry = { id: cleanId, label: cleanLabel, host: cleanHost, token: cleanToken };
293	                const updated = [...existingCredentials];
294	                updated[existingIndex] = savedEntry;
295	                appConfig.gitCredentials = updated;
296	                auditOperation = 'update-credential';
297	            }
298	        } else {
299	            // --- Create path: no id provided — auto-generate from label ---
300	            const existingIds = new Set(existingCredentials.map((e) => e.id));

301	            const newId = generateUniqueId(cleanLabel, existingIds);
302	            savedEntry = { id: newId, label: cleanLabel, host: cleanHost, token: cleanToken };
303	            appConfig.gitCredentials = [...existingCredentials, savedEntry];
304	            auditOperation = 'create-credential';
305	        }
306	
307	        // Persist to disk.
308	        saveConfigField('gitCredentials', appConfig.gitCredentials, configPath);
309	
310	        // Audit log — never include the token value.
311	        errorLogManager?.append({
312	            Severity: 'warning',
313	            Source: 'credential-audit',
314	            Operation: auditOperation,
315	            Context: {},
316	            Message: `Credential "${savedEntry.id}" (label: "${savedEntry.label}", host: "${savedEntry.host}") was ${auditOperation === 'create-credential' ? 'created' : 'updated'}.`,
317	        });
318	
319	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
320	    });
