287	/**
288	 * Reads `config.json`, sets or removes a single top-level field, and writes the
289	 * file back via `writeJsonFile()`. All other fields — including `_instructions`
290	 * — are preserved.
291	 *
292	 * @param field - The top-level key to modify (e.g. `"gitCredentials"`).
293	 * @param value - The value to set, or `undefined` to remove the field.
294	 * @param configPath - Optional absolute path to the config file. Defaults to
295	 *   the tool-root `config.json`.
296	 * @throws {Error} If `config.json` cannot be read or written.
297	 */
298	export function saveConfigField(
299	    field: string,
300	    value: unknown,
301	    configPath?: string,
302	): void {
303	    const resolvedConfigPath = configPath ?? getConfigPath();
304	    const raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
305	
306	    if (value === undefined) {
307	        delete raw[field];
308	    } else {
309	        raw[field] = value;
